sys_script_include.script:
var HocNotificationHelper = Class.create();
HocNotificationHelper.prototype = {
    type: 'HocNotificationHelper'
};

HocNotificationHelper.formatDate = function(date) {
    var gdt = new GlideDateTime(date);
    var dateString = gdt.getDisplayValue();
    var year = dateString.substring(0, 4);
    var month = dateString.substring(5, 7);
    var day = dateString.substring(8, 10);
    var time = new GlideDateTime(date).getDisplayValue().slice(11);

    var months = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
    var daysOfWeek = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];

    var jsDate = new Date(year, month - 1, day);
    var formattedDate = gs.getMessage(daysOfWeek[jsDate.getDay()]) + ", " + gs.getMessage(months[month - 1]) + " " + parseInt(day, 10) + ", " + year + ", " + time;

    return formattedDate;

};

HocNotificationHelper.formatDatechangeapproval = function(date, lang) {

   var gdt = new GlideDateTime(date);
    var dateString = gdt.getDisplayValue();
    var year = dateString.substring(0, 4);
    var month = dateString.substring(5, 7);
    var day = dateString.substring(8, 10);
    var time = new GlideDateTime(date).getDisplayValue().slice(11);

    var months = {
        "en": ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"],
        "fq": ["Janvier", "Février", "Mars", "Avril", "Mai", "Juin", "Juillet", "Août", "Septembre", "Octobre", "Novembre", "Décembre"]
    };

    var daysOfWeek = {
        "en": ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"],
        "fq": ["Dimanche", "Lundi", "Mardi", "Mercredi", "Jeudi", "Vendredi", "Samedi"]
    };
    lang = lang || "en";
    var jsDate = new Date(year, month - 1, day);

    if (lang === "fq") {
        formattedDate = gs.getMessage(daysOfWeek[lang][jsDate.getDay()]) + " " +
            parseInt(day, 10) + " " +
            gs.getMessage(months[lang][month - 1]) + " " +
            year + ", " + time + " ";
    } else {
        formattedDate = gs.getMessage(daysOfWeek[lang][jsDate.getDay()]) + ", " +
            gs.getMessage(months[lang][month - 1]) + " " +
            parseInt(day, 10) + ", " + year + ", " + time + " ";
    }

    return formattedDate;


};
